/* Apply border-box once, to everything. Every framework does this. */
*, *::before, *::after {
  box-sizing: border-box;
}

/* Without it:
   .card { width: 300px; padding: 20px; border: 1px solid; }
   -> content 300 + padding 40 + border 2 = 342px on screen.
   Two of these at width: 50% overflow their container, and nothing in the
   CSS shows you why. */

:root {
  --gap: 1rem;
  --surface: #ffffff;
  --ink: #1a1a1a;
  --line: #e2e2e2;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --surface: #161616;
    --ink: #f0f0f0;
    --line: #333333;
  }
}

body {
  margin: 0;
  background: var(--surface);          /* always set an explicit background */
  color: var(--ink);
  font: 16px/1.6 system-ui, sans-serif;
}

.card {
  width: 300px;              /* with border-box, this IS 300px on screen */
  padding: var(--gap);
  border: 1px solid var(--line);
  border-radius: 8px;

  /* Logical properties: adapt to writing direction, so a right-to-left
     language needs no separate stylesheet. */
  margin-inline: auto;       /* left and right in LTR, mirrored in RTL */
  margin-block-end: var(--gap);
}

/* display changes which rules apply. */
.inline-thing {
  display: inline;
  width: 200px;              /* IGNORED: inline elements size to their content */
  height: 50px;              /* also ignored */
  padding-block: 20px;       /* applied, but does NOT push neighbours apart */
}

.fixed-thing {
  display: inline-block;     /* the one-word fix: flows inline, accepts size */
  width: 200px;
  height: 50px;
}

/* ---------- flexbox: one axis ---------- */
.toolbar {
  display: flex;
  align-items: center;        /* vertical centring across the cross axis */
  gap: 0.75rem;               /* no margins, no :last-child exception */
  flex-wrap: wrap;            /* move to a new line rather than squash */
}

.toolbar .spacer { flex: 1; } /* absorbs the remaining space, pushing the rest right */

.card {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.card .body { flex: 1; }      /* footers align across cards of differing height */


/* ---------- grid: two axes ---------- */

/* A responsive grid with NO media query. Columns are at least 250px, as many
   fit as will, and they share the leftover space. One column on a phone,
   four on a desktop, automatically. */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1rem;
}

/* Page layout drawn as text: unusually readable, and rearranging it for a
   phone means rewriting the picture. */
.page {
  display: grid;
  min-height: 100dvh;                    /* dvh: correct with mobile browser chrome */
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  gap: 1rem;
}

.page > header  { grid-area: header; }
.page > nav     { grid-area: sidebar; }
.page > main    { grid-area: main; }
.page > footer  { grid-area: footer; }

@media (max-width: 40rem) {
  .page {
    grid-template-areas:                 /* the same picture, restacked */
      "header"
      "main"
      "sidebar"
      "footer";
    grid-template-columns: 1fr;
  }
}

/* ---------- centring, in two lines ---------- */
.centre {
  display: grid;
  place-items: center;
}

/* The single most common accessibility failure on the web. */
button:focus { outline: none; }        /* NEVER do this without a replacement */

/* :focus-visible shows a ring for keyboard users and not on mouse clicks —
   which is what people actually wanted when they removed the outline. */
:focus-visible {
  outline: 3px solid #4d90fe;
  outline-offset: 2px;
}

/* Contrast is measurable, not a matter of taste. */
.text-muted { color: #767676; }   /* 4.54:1 on white — passes AA */
.text-faint { color: #999999; }   /* 2.85:1 on white — FAILS, common in placeholders */

/* Visible to screen readers, not on screen. For skip links and extra context. */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

/* A skip link: the first tab stop, letting a keyboard user jump past the nav. */
.skip-link {
  position: absolute; top: -3rem; left: 1rem;
  background: #fff; padding: 0.5rem 1rem; z-index: 100;
}
.skip-link:focus { top: 1rem; }

/*
<a class="skip-link" href="#main">Skip to main content</a>

<!-- Icon-only button: the label is what a screen reader announces. -->
<button aria-label="Close dialog">
  <svg aria-hidden="true" ...></svg>      <!-- decorative: hide from the tree -->
</button>

<!-- Disclosure: aria-expanded is updated in JS when it toggles. -->
<button aria-expanded="false" aria-controls="filters">Filters</button>
<div id="filters" hidden>...</div>

<!-- Dynamic results: without aria-live, a screen reader user gets no
     indication that anything changed. polite waits for a pause. -->
<div role="status" aria-live="polite" class="visually-hidden">
  14 results found
</div>

<!-- Error state: colour AND text AND a programmatic association. Greyscale
     test: the meaning survives without the red. -->
<input id="email" aria-invalid="true" aria-describedby="email-error">
<p id="email-error" class="error">
  <svg aria-hidden="true">...</svg>
  Enter a valid email address
</p>
*/

// --- coercion, and why === always ----------------------------------------
console.log(0 == "");             // true   — nobody wants this
console.log(0 == "0");            // true
console.log("" == "0");           // false  — not even transitive
console.log(null == undefined);   // true
console.log(NaN == NaN);          // false  — NaN equals nothing, including itself

console.log(0 === "");            // false  — predictable
console.log(Number.isNaN(NaN));   // true   — how to actually test for NaN

// --- typeof quirks --------------------------------------------------------
console.log(typeof null);         // "object"  — a bug from 1995, unfixable
console.log(typeof []);           // "object"
console.log(Array.isArray([]));   // true      — the correct check

// --- floating point -------------------------------------------------------
console.log(0.1 + 0.2);                    // 0.30000000000000004
console.log(0.1 + 0.2 === 0.3);            // false

const totalPence = 10 + 20;                // work in minor units for money
console.log((totalPence / 100).toFixed(2)); // "0.30"

// --- falsy values, and the operator that respects zero -------------------
const falsy = [false, 0, -0, "", null, undefined, NaN];
// Everything else is truthy, INCLUDING "0", "false", [] and {}.

function renderCount(count) {
  if (count) return `${count} items`;      // WRONG: hides a legitimate 0
  return "no items";
}

// || falls back on ANY falsy value, silently replacing a real zero.
const pageSize1 = userSetting || 20;       // a userSetting of 0 becomes 20

// ?? falls back only on null/undefined.
const pageSize2 = userSetting ?? 20;       // a userSetting of 0 stays 0

// --- optional chaining removes defensive nesting -------------------------
const city = response?.data?.customer?.address?.city ?? "Unknown";
// Without ?., this throws if any level is missing.

// --- const by default -----------------------------------------------------
const items = [];        // the BINDING is constant; the array is still mutable
items.push(1);           // fine
// items = [];           // TypeError

let index = 0;           // only when reassignment is genuinely needed
// var count = 0;        // never: function-scoped and hoisted

// --- closures: private state without a global ----------------------------
function createCounter(start = 0) {
  let count = start;                    // not reachable from outside
  return {
    increment: () => ++count,
    get value() { return count; },
  };
}

const counter = createCounter();
counter.increment();
console.log(counter.value);             // 1
// console.log(counter.count);          // undefined — genuinely private

// A closure keeps everything it references alive. This holds the entire
// 10MB buffer in memory just to report its length.
function makeLeak() {
  const huge = new Array(10_000_000).fill("x");
  return () => huge.length;             // `huge` can never be collected
}
function noLeak() {
  const huge = new Array(10_000_000).fill("x");
  const length = huge.length;           // capture only what is needed
  return () => length;
}

// --- `this` depends on how a function is CALLED ---------------------------
const timer = {
  seconds: 0,

  startBroken() {
    // A regular function called by setTimeout: `this` is not `timer`.
    setInterval(function () {
      this.seconds++;                   // TypeError — `this` is undefined
    }, 1000);
  },

  startWorking() {
    // An arrow has no `this` of its own, so it uses the enclosing one.
    setInterval(() => {
      this.seconds++;                   // `this` is `timer`
    }, 1000);
  },
};

// Passing a method detaches it from its object — the classic bug.
const button = document.querySelector("button");
button.addEventListener("click", timer.startWorking);          // `this` is the button
button.addEventListener("click", () => timer.startWorking());  // correct
button.addEventListener("click", timer.startWorking.bind(timer)); // also correct

// --- array methods: mutating vs not --------------------------------------
const scores = [3, 1, 2];

const sortedCopy = scores.toSorted();   // [1, 2, 3], `scores` unchanged
scores.sort();                          // MUTATES: scores is now [1, 2, 3]

const doubled = scores.map(n => n * 2);
const large   = scores.filter(n => n > 1);
const total   = scores.reduce((sum, n) => sum + n, 0);
const first   = scores.find(n => n > 1);            // undefined if none match

// --- spread is SHALLOW ----------------------------------------------------
const defaults = { theme: "dark", layout: { columns: 2 } };
const settings = { ...defaults, theme: "light" };
settings.layout.columns = 3;
console.log(defaults.layout.columns);   // 3 — the nested object is shared

// --- textContent vs innerHTML --------------------------------------------
const name = getUserInput();             // e.g. '<img src=x onerror="steal()">'

element.innerHTML = name;                // XSS: the onerror handler executes
element.textContent = name;              // safe: inserted as text, not parsed

// --- event delegation -----------------------------------------------------
// One hundred listeners, and none of them work for rows added later:
document.querySelectorAll(".row-delete").forEach(button => {
  button.addEventListener("click", handleDelete);
});

// One listener, and it works for rows added at any point in the future.
document.querySelector("#rows").addEventListener("click", (event) => {
  const button = event.target.closest(".row-delete");
  if (!button) return;                   // the click was somewhere else
  handleDelete(button.dataset.rowId);
});

// --- layout thrashing -----------------------------------------------------
// Each read after a write forces a synchronous layout recalculation. With
// 200 boxes that is 200 forced layouts and a visibly janky page.
for (const box of boxes) {
  box.style.height = box.offsetHeight + 10 + "px";   // write, read, write, read...
}

// Read everything first, then write everything. One layout.
const heights = boxes.map(box => box.offsetHeight);  // all reads
boxes.forEach((box, i) => {                          // all writes
  box.style.height = heights[i] + 10 + "px";
});

// --- build off-document, insert once -------------------------------------
const fragment = document.createDocumentFragment();
for (const item of items) {
  const li = document.createElement("li");
  li.textContent = item.name;
  fragment.append(li);                   // not in the document yet: no reflow
}
list.append(fragment);                   // one insertion, one reflow

// --- AbortController removes a whole group of listeners ------------------
const controller = new AbortController();
const { signal } = controller;

window.addEventListener("resize", onResize, { signal });
window.addEventListener("scroll", onScroll, { signal });
input.addEventListener("input", onInput, { signal });

controller.abort();   // all three removed. Far harder to get wrong than
                      // three matching removeEventListener calls with the
                      // exact same function references.

// --- ordering: microtasks drain before the next macrotask ----------------
console.log("1 sync");

setTimeout(() => console.log("4 timer (macrotask)"), 0);

Promise.resolve().then(() => console.log("3 promise (microtask)"));

console.log("2 sync");

// Output: 1 sync, 2 sync, 3 promise, 4 timer
// The promise callback was queued AFTER the timer and still runs first,
// because the microtask queue is drained completely before the next macrotask.


// --- blocking the thread --------------------------------------------------
function freezeThePage() {
  const end = Date.now() + 5000;
  while (Date.now() < end) { /* spin */ }
  // For five seconds: no clicks processed, no animation, no repaint. The tab
  // is not slow, it is blocked.
}

// --- chunking: yield so the browser can paint ----------------------------
async function processInChunks(items, chunkSize = 500) {
  for (let i = 0; i < items.length; i += chunkSize) {
    for (const item of items.slice(i, i + chunkSize)) {
      expensiveWork(item);
    }
    // Yield: the browser paints and handles input between chunks.
    await new Promise(resolve => setTimeout(resolve, 0));
  }
}

// --- a Web Worker: genuinely off the main thread -------------------------
const worker = new Worker("parse-worker.js");
worker.postMessage({ csv: hugeString });
worker.onmessage = (event) => render(event.data.rows);
// The worker cannot touch the DOM — that is the point; the DOM is not
// thread-safe. It computes and posts the result back.


// --- debounce: wait until the activity STOPS (search input) --------------
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}
searchInput.addEventListener("input", debounce(runSearch, 300));

// --- throttle: at most once per interval (scroll position) ---------------
function throttle(fn, interval = 100) {
  let last = 0;
  return (...args) => {
    const now = Date.now();
    if (now - last >= interval) { last = now; fn(...args); }
  };
}
window.addEventListener("scroll", throttle(updateScrollIndicator, 100));

// --- visual work belongs on the frame boundary ---------------------------
let ticking = false;
window.addEventListener("scroll", () => {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(() => {          // runs just before the next paint
    header.classList.toggle("compact", window.scrollY > 100);
    ticking = false;
  });
});

// --- the trap: fetch does not reject on HTTP errors ----------------------
async function loadBroken(id) {
  const response = await fetch(`/api/customers/${id}`);
  return response.json();        // on a 500, tries to parse an HTML error page
}                                // -> "Unexpected token '<'", far from the cause

async function load(id, signal) {
  const response = await fetch(`/api/customers/${id}`, {
    signal: signal ?? AbortSignal.timeout(10_000),   // fetch has NO default timeout
    headers: { Accept: "application/json" },
  });

  if (!response.ok) {            // 404 and 500 FULFIL the promise
    throw new ApiError(`Request failed (${response.status})`, response.status);
  }
  return response.json();
}

// --- independent requests in parallel -------------------------------------
async function loadDashboardSequential(id) {
  const customer = await load(`/api/customers/${id}`);   // 300ms
  const usage    = await load(`/api/usage/${id}`);       // 400ms
  return { customer, usage };                            // 700ms total
}

async function loadDashboard(id) {
  const [customer, usage] = await Promise.all([          // both start now
    load(`/api/customers/${id}`),
    load(`/api/usage/${id}`),
  ]);
  return { customer, usage };                            // 400ms total
}

// allSettled when a partial result is still useful.
async function loadWithOptionalExtras(id) {
  const [customer, usage] = await Promise.allSettled([
    load(`/api/customers/${id}`),
    load(`/api/usage/${id}`),
  ]);
  if (customer.status === "rejected") throw customer.reason;   // required
  return {
    customer: customer.value,
    usage: usage.status === "fulfilled" ? usage.value : null,  // optional
  };
}

// --- the out-of-order race ------------------------------------------------
let inFlight = null;

async function search(term) {
  inFlight?.abort();                     // cancel the previous request
  const controller = new AbortController();
  inFlight = controller;

  try {
    const results = await load(`/api/search?q=${encodeURIComponent(term)}`,
                               controller.signal);
    render(results);
  } catch (error) {
    if (error.name === "AbortError") return;    // superseded: not a failure
    // Never just console.error: the user is still watching a spinner.
    showError("Could not load results. Check your connection and try again.");
  }
}
// Without the abort, the response for "ab" can arrive after the one for "abc"
// and overwrite the correct results with stale ones.

// One status field: impossible to be loading AND errored at once, which
// separate isLoading/error booleans would allow.
/** @typedef {{status:"idle"} | {status:"loading"} | {status:"error", message:string}
 *          | {status:"empty"} | {status:"data", items:Array}} ViewState */

/** @type {ViewState} */
let state = { status: "idle" };

function setState(next) {
  state = next;
  render();
}

async function loadOrders(customerId) {
  // Delay the spinner: a request that finishes in 80ms should not flash one.
  const spinnerTimer = setTimeout(() => {
    if (state.status === "loading") showSpinner();
  }, 250);

  setState({ status: "loading" });

  try {
    const orders = await load(`/api/customers/${customerId}/orders`);
    setState(orders.length === 0
      ? { status: "empty" }                 // NOT an error — a different thing
      : { status: "data", items: orders });
  } catch (error) {
    if (error.name === "AbortError") return;
    setState({
      status: "error",
      // Says what happened and implies what to do. Not "Error: 500".
      message: error.status === 404
        ? "We could not find that customer."
        : "We could not load these orders. Try again in a moment.",
    });
  } finally {
    clearTimeout(spinnerTimer);
    hideSpinner();
  }
}

function render() {
  const root = document.querySelector("#orders");
  const live = document.querySelector("#orders-status");   // aria-live region

  switch (state.status) {
    case "idle":
      root.replaceChildren();
      break;

    case "loading":
      root.replaceChildren(skeletonRows(3));
      live.textContent = "Loading orders";       // announced to screen readers
      break;

    case "empty":
      // An opportunity, not a dead end.
      root.replaceChildren(emptyState({
        title: "No orders yet",
        body: "When this customer places an order it will appear here.",
        action: { label: "Create an order", onClick: openCreateOrder },
      }));
      live.textContent = "No orders found";
      break;

    case "error":
      // A retry button: most failures are transient, and reloading the page
      // would lose the user's place.
      root.replaceChildren(errorState({
        message: state.message,
        action: { label: "Try again", onClick: () => loadOrders(currentId) },
      }));
      live.textContent = state.message;
      break;

    case "data":
      root.replaceChildren(orderTable(state.items));
      live.textContent = `${state.items.length} orders found`;
      break;
  }
}

