// --- model the domain -----------------------------------------------------
type OrderStatus = "draft" | "submitted" | "shipped" | "cancelled";

interface Order {
  readonly id: string;
  customerId: string;
  status: OrderStatus;
  lines: OrderLine[];
  placedAt: string;          // ISO 8601; a Date does not survive JSON
  cancelledAt?: string;      // optional: may be absent entirely
}

interface OrderLine {
  sku: string;
  quantity: number;
  unitPriceMinor: number;    // pence, not pounds — never a float for money
}

// A typo is now a compile error rather than a silent undefined at runtime.
function describe(order: Order): string {
  // return order.custmerId;            // error: did you mean 'customerId'?
  return `${order.customerId}: ${order.status}`;
}

// A literal union autocompletes and rejects typos.
function setStatus(order: Order, status: OrderStatus): Order {
  return { ...order, status };
}
// setStatus(order, "shiped");          // error: not assignable to OrderStatus

// --- unknown, not any -----------------------------------------------------
async function loadOrderUnsafe(id: string): Promise<Order> {
  const response = await fetch(`/api/orders/${id}`);
  return response.json();              // typed as `any`: a total lie. The
}                                      // compiler now trusts data it never saw.

function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const o = value as Record<string, unknown>;
  return typeof o.id === "string"
      && typeof o.customerId === "string"
      && typeof o.status === "string"
      && Array.isArray(o.lines);
}

async function loadOrder(id: string): Promise<Order> {
  const response = await fetch(`/api/orders/${id}`);
  if (!response.ok) throw new Error(`Failed: ${response.status}`);

  const data: unknown = await response.json();   // honest about what we have
  if (!isOrder(data)) {
    // Fails HERE with a clear message, not three components away as an
    // "undefined is not a function".
    throw new Error("Unexpected response shape from /api/orders");
  }
  return data;                                   // narrowed to Order
}

