// --- a cast is a promise; narrowing is a proof ---------------------------
function badLength(value: unknown): number {
  return (value as string).length;     // no check: crashes if it is a number
}

function length(value: unknown): number {
  if (typeof value === "string") return value.length;   // narrowed to string
  if (Array.isArray(value)) return value.length;        // narrowed to unknown[]
  return 0;
}

// --- discriminated union: the pattern for "one of these outcomes" --------
type LoadResult =
  | { status: "loading" }
  | { status: "empty" }
  | { status: "data"; orders: Order[] }
  | { status: "error"; message: string; retryable: boolean };

function renderResult(result: LoadResult): string {
  switch (result.status) {
    case "loading":
      return "Loading...";
    case "empty":
      return "No orders yet";
    case "data":
      return `${result.orders.length} orders`;      // .orders available here
      // return result.message;                     // error: not on this variant
    case "error":
      return result.retryable ? `${result.message} Try again.` : result.message;
    default: {
      // Exhaustiveness: adding a fifth variant makes THIS line fail to compile,
      // pointing at every switch that must now handle it.
      const exhaustive: never = result;
      return exhaustive;
    }
  }
}

// --- narrowing with `in` and instanceof ----------------------------------
type ApiFailure = { code: number } | Error;

function describeFailure(failure: ApiFailure): string {
  if (failure instanceof Error) return failure.message;   // narrowed to Error
  if ("code" in failure) return `HTTP ${failure.code}`;   // narrowed to the object
  return "Unknown failure";
}

// --- satisfies: validate without losing the literal types ----------------
const themes = {
  light: { bg: "#ffffff", ink: "#1a1a1a" },
  dark:  { bg: "#161616", ink: "#f0f0f0" },
} satisfies Record<string, { bg: string; ink: string }>;

type ThemeName = keyof typeof themes;     // "light" | "dark", not just string
// With `: Record<string, ...>` instead, ThemeName would widen to `string`.

// --- a schema library so the type and the check cannot drift -------------
import { z } from "zod";

const OrderSchema = z.object({
  id: z.string(),
  customerId: z.string(),
  status: z.enum(["draft", "submitted", "shipped", "cancelled"]),
  lines: z.array(z.object({
    sku: z.string(),
    quantity: z.number().int().positive(),
    unitPriceMinor: z.number().int().nonnegative(),
  })),
  placedAt: z.string().datetime(),
});

type OrderFromSchema = z.infer<typeof OrderSchema>;   // derived from the schema

async function fetchOrder(id: string): Promise<OrderFromSchema> {
  const response = await fetch(`/api/orders/${id}`);
  // Validates at runtime AND narrows the type. One definition, so the check
  // and the type can never disagree.
  return OrderSchema.parse(await response.json());
}

