// --- by hand: every state change must be manually propagated -------------
let orders = [];
let status = "idle";

async function loadOrders(customerId) {
  status = "loading";
  document.querySelector("#spinner").hidden = false;      // remember this
  document.querySelector("#error").hidden = true;         // and this
  document.querySelector("#list").innerHTML = "";         // and this

  try {
    orders = await fetchOrders(customerId);
    status = "data";
    renderList(orders);                                   // and this
    document.querySelector("#count").textContent = orders.length;   // and this
  } catch {
    status = "error";
    document.querySelector("#error").hidden = false;      // and this
  } finally {
    document.querySelector("#spinner").hidden = true;     // and this
  }
}
