// --- Angular: describe the UI for a state --------------------------------
import { Component, computed, inject, input, resource } from "@angular/core";

@Component({
  selector: "app-orders",
  standalone: true,
  template: `
    @if (ordersResource.isLoading()) {
      <app-skeleton rows="3" />
    } @else if (ordersResource.error()) {
      <app-error [message]="errorMessage()" (retry)="ordersResource.reload()" />
    } @else if (orders().length === 0) {
      <app-empty title="No orders yet" />
    } @else {
      <p>{{ orders().length }} orders</p>
      <ul>
        @for (order of orders(); track order.id) {
          <li>{{ order.customerId }} — {{ order.status }}</li>
        }
      </ul>
    }
  `,
})
export class OrdersComponent {
  customerId = input.required<string>();
  private api = inject(OrdersApi);        // dependency injection: fake it in tests

  ordersResource = resource({
    request: () => ({ customerId: this.customerId() }),
    loader: ({ request }) => this.api.list(request.customerId),
  });

  // Derived state: recomputed automatically, never manually synchronised.
  orders = computed(() => this.ordersResource.value() ?? []);
  errorMessage = computed(() =>
    this.ordersResource.error() ? "Could not load orders." : "");
}
// All four states are declared in one place. Adding a fifth piece of UI that
// depends on `orders` requires nothing to be remembered.

import { describe, expect, it, vi } from "vitest";
import { render, screen } from "@testing-library/angular";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { setupServer } from "msw/node";

// Intercept at the NETWORK boundary. Our real fetching code, error handling
// and parsing all run — and the test survives refactoring them.
const server = setupServer();
beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

describe("OrdersComponent", () => {

  it("shows the orders once they load", async () => {
    server.use(http.get("/api/customers/:id/orders", () =>
      HttpResponse.json([
        { id: "1", customerId: "C-1", status: "shipped", lines: [] },
        { id: "2", customerId: "C-1", status: "draft", lines: [] },
      ])));

    await render(OrdersComponent, { inputs: { customerId: "C-1" } });

    // Found by what the user SEES, not by a CSS class that will be renamed.
    expect(await screen.findByText("2 orders")).toBeInTheDocument();
  });

  it("shows an empty state, not an error, when there are no orders", async () => {
    server.use(http.get("/api/customers/:id/orders", () => HttpResponse.json([])));

    await render(OrdersComponent, { inputs: { customerId: "C-1" } });

    // Empty and error are different situations and must look different.
    expect(await screen.findByText("No orders yet")).toBeInTheDocument();
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });

  it("shows an error with a working retry when the request fails", async () => {
    let attempts = 0;
    server.use(http.get("/api/customers/:id/orders", () => {
      attempts += 1;
      return attempts === 1
        ? new HttpResponse(null, { status: 500 })
        : HttpResponse.json([{ id: "1", customerId: "C-1", status: "draft", lines: [] }]);
    }));

    await render(OrdersComponent, { inputs: { customerId: "C-1" } });

    expect(await screen.findByText(/could not load/i)).toBeInTheDocument();

    // By role and accessible name: if this query fails, a screen reader user
    // cannot find the button either. The test catches that for free.
    await userEvent.click(screen.getByRole("button", { name: /try again/i }));

    expect(await screen.findByText("1 orders")).toBeInTheDocument();
  });
});

